let activeEdit='space';
function editPieces(key){return curatedEdits[key].ids.map(id=>items.find(p=>p.id===id)).filter(Boolean)}
function editContent(key){const edit=curatedEdits[key];return `<div class="edit-composition"><figure class="edit-image"><img src="${asset(edit.image)}" alt="${say(edit.altRu,edit.altEn)}" loading="lazy" width="1536" height="1024"></figure><div class="edit-related" aria-label="${say('Предметы подборки','Pieces in this edit')}">${editPieces(key).map(p=>`<a href="#/piece/${p.id}" class="edit-mini"><img src="${asset(p.img)}" alt="" loading="lazy"><span><small>${tr(p.cat)}</small><strong>${esc(tx(p.name))}</strong></span></a>`).join('')}</div></div><div class="edit-story"><p class="eyebrow">${say('ОТОБРАНО AMRA','CURATED BY AMRA')}</p><h3>${say(edit.titleRu,edit.titleEn)}</h3><p class="edit-description">${say(edit.textRu,edit.textEn)}</p><a href="#/edit/${key}" class="button edit-cta">${say(edit.ctaRu,edit.ctaEn)}</a><p class="edit-note">${say('Подборка из демонстрационной коллекции','An edit from the concept collection')}</p></div>`}
function discovery(){return `<section class="curated-edits" id="curated-edits"><div class="wrap"><div class="edits-heading"><div><p class="eyebrow">${say('ПОДБОРКИ AMRA','THE AMRA EDITS')}</p><h2>${say('Разные поводы.<br><em>Ваш выбор.</em>','Different occasions.<br><em>Your choice.</em>')}</h2></div><p>${say('Для пространства, для себя или для особенного человека. Откройте коллекцию с новой стороны.','For a room, for yourself or for someone special. Discover a different way into the collection.')}</p></div><div class="edit-controls" role="group" aria-label="${say('Выберите подборку','Choose an edit')}">${Object.entries(curatedEdits).map(([key,edit])=>`<button type="button" data-edit="${key}" aria-pressed="${activeEdit===key}" aria-controls="edit-stage" class="edit-choice ${activeEdit===key?'active':''}"><span>${say(edit.ru,edit.en)}</span></button>`).join('')}</div><div class="edit-stage" id="edit-stage" aria-live="polite">${editContent(activeEdit)}</div></div></section>`}
function setEdit(key){if(!curatedEdits[key]||activeEdit===key)return;activeEdit=key;document.querySelectorAll('[data-edit]').forEach(b=>{b.classList.toggle('active',b.dataset.edit===key);b.setAttribute('aria-pressed',b.dataset.edit===key)});$('#edit-stage').innerHTML=editContent(key);}
function editCollection(key){if(!curatedEdits[key])return notfound();const edit=curatedEdits[key];return `<div class="wrap"><div class="page-head">${breadcrumb(say(edit.ru,edit.en))}<p class="eyebrow">${say('ПОДБОРКИ AMRA','THE AMRA EDITS')}</p><h1>${say(edit.ru,edit.en)}</h1><p class="description">${say(edit.textRu,edit.textEn)}</p></div><div class="product-grid catalog-grid catalog-bottom">${editPieces(key).map(card).join('')}</div><a class="text-link edit-back" href="#/">${say('Вернуться на главную','Back to home')}</a></div>${concierge()}`}
const genesisNames=['Amazing Life in the Desert','City of the Future','Loyalty to Tradition','Home for Everyone','Dubai Lifestyle','You Are Always Safe','Where Dreams Come True','No Limit','What’s Next?','Number One'];
const genesisBase='https://opensea.io/item/ethereum/0x3a5aa67bbcbec3615c022f880254dfa44d3ad765/';
const genesisCollection='https://opensea.io/AMRA-NFT/holdings?collectionSlugs=amra-dubai-genesis&view=grid';
const legacyDigitalIds={'falcon-view':'genesis-1','chromatic-orbit':'genesis-2','other-worlds':'genesis-3','violet-signal':'genesis-4','solar-tide':'genesis-5'};
for(let i=items.length-1;i>=0;i--)if(items[i].cat==='digital')items.splice(i,1);
genesisNames.forEach((name,i)=>items.push({id:'genesis-'+(i+1),cat:'digital',name:{ru:name,en:name},img:'genesis-'+String(i+1).padStart(2,'0')+'.webp',sub:{ru:'AMRA Dubai Genesis · #'+String(i+1).padStart(3,'0'),en:'AMRA Dubai Genesis · #'+String(i+1).padStart(3,'0')},price:null,material:{ru:'Цифровая работа / NFT',en:'Digital work / NFT'},size:{ru:'Подробности на OpenSea',en:'Details on OpenSea'},collection:'AMRA Dubai Genesis',desc:{ru:'Цифровая работа из коллекции AMRA Dubai Genesis. Изображение и название представлены по материалам коллекции на OpenSea. Полное описание и актуальные условия — на странице работы.',en:'A digital work from AMRA Dubai Genesis. Image and title are presented from the collection on OpenSea. Visit the work’s page for its full description and current terms.'},group:'own',external:genesisBase+(i+1),token:i+1}));
items.forEach(p=>{if(p.size==='По запросу / On enquiry')p.size={ru:'По запросу',en:'On enquiry'}});
saved=[...new Set(saved.map(id=>legacyDigitalIds[id]||id))].filter(id=>items.some(p=>p.id===id));
function nftPiece(p){return `<div class="wrap"><div class="page-head">${breadcrumb(tr('digital')+' / '+tx(p.name))}</div><div class="piece-layout nft-piece"><div class="piece-image"><img src="${asset(p.img)}" alt="${esc(tx(p.name))}" width="500" height="500" fetchpriority="high"></div><div class="piece-info"><p class="eyebrow accent">AMRA DUBAI GENESIS / #${genesisNumber(p.token)}</p><h1>${esc(tx(p.name))}</h1><p class="summary">${esc(tx(p.desc))}</p><div class="specs"><div class="spec"><span>${tr('origin')}</span><span>AMRA Dubai Genesis</span></div><div class="spec"><span>${tr('material')}</span><span>${tx(p.material)}</span></div><div class="spec"><span>${say('Сеть','Network')}</span><span>Ethereum</span></div></div><a class="button" href="${p.external}" target="_blank" rel="noopener noreferrer">${say('Смотреть работу на OpenSea','View the work on OpenSea')}${I.arrow}</a><button class="text-link" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?tr('saved'):tr('save')}</button><a class="text-link nft-back" href="#/digital">${say('Вся коллекция Dubai Genesis','All of Dubai Genesis')}</a></div></div></div>`}
function copyRequest(){const el=$('.preview-message');if(!el)return;const fallback=()=>{const range=document.createRange();range.selectNodeContents(el);const sel=getSelection();sel.removeAllRanges();sel.addRange(range);notify(say('Текст выделен — скопируйте его','Text selected — copy it to continue'))};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(el.textContent).then(()=>notify(tr('copied'))).catch(fallback);else fallback()}
let activeGenesis=1;
function genesisNumber(n){return String(n).padStart(3,'0')}
function genesisImage(n){return asset('genesis-'+String(n).padStart(2,'0')+'.webp')}
function perfumeStory(){return `<section class="perfume-journal" id="perfume-story"><div class="wrap"><div class="journal-top"><p class="eyebrow">02 / ${say('ПАРФЮМЕРИЯ','PERFUMERY')}</p><span class="eyebrow">THE SCENT JOURNAL — 01</span></div><div class="journal-heading"><h2>${say('У каждого аромата<br><em>есть первая нота.</em>','Every fragrance begins<br><em>with a first note.</em>')}</h2><p>${say('За флаконом — замысел, поиск и десятки маленьких решений. Загляните туда, где рождается характер аромата.','Behind a bottle lie an idea, a search and dozens of small decisions. Step inside the making of a fragrance.')}</p></div><div class="journal-spread"><figure class="atelier-photo"><img src="${asset('perfume-atelier.webp')}" alt="${say('Парфюмер работает с блоттером и ингредиентами в мастерской — концептуальная иллюстрация','Perfumer working with a blotter and ingredients in a workshop — concept illustration')}" loading="lazy" width="1536" height="1024"><figcaption><span>ATELIER / ÉTUDE 01</span><span>${say('Наблюдения за невидимым','Studies of the invisible')}</span></figcaption></figure><div class="journal-story"><p class="eyebrow">${say('ИСТОРИЯ ОДНОГО АРОМАТА','THE STORY OF A FRAGRANCE')}</p><h3>${say('Сохранить <br><em>тепло момента.</em>','To hold <br><em>a moment’s warmth.</em>')}</h3><p>${say('Представьте мастерскую перед закатом. На столе — кожура бергамота, сухой ирис и кедровая стружка. Парфюмер пытается сохранить ощущение дня, который не хочется отпускать. Так начинается наша история «Тёплый след».','Imagine a workshop before sunset. Bergamot peel, dry iris and cedar shavings rest on the table. A perfumer is trying to capture a day they do not want to let go. This is the beginning of our story, “A Warm Trace”.')}</p><div class="scent-chapters">${[[say('01 / Замысел','01 / The idea'),say('Не повторить запах места, а передать чувство: солнце на камне, лёгкий ветер и спокойствие вечера.','Not to reproduce a place’s smell, but to express a feeling: sunlight on stone, a light breeze and the quiet of evening.')],[say('02 / Поиск баланса','02 / Finding balance'),say('Бергамот даёт светлое начало, ирис смягчает переход, а кедр оставляет тёплый древесный след.','Bergamot opens with brightness, iris softens the transition and cedar leaves a warm, woody trail.')],[say('03 / Последний штрих','03 / The final touch'),say('Композицию снова пробуют на блоттере и на коже: первые минуты, несколько часов спустя, на следующий день. История становится цельной, когда ни одна нота не спорит с другой.','The composition returns to the blotter and the skin: in its first minutes, hours later and the following day. The story is complete when its notes fall into conversation.')]].map(([t,p],i)=>`<details ${i===0?'open':''}><summary>${t}<span aria-hidden="true">+</span></summary><p>${p}</p></details>`).join('')}</div><p class="journal-concept">${say('Временная вымышленная история · иллюстрация концепции','Temporary fictional story · concept illustration')}</p></div></div><div class="journal-foot"><div class="note-line"><span>${say('ПАЛИТРА ИСТОРИИ','THE STORY’S PALETTE')}</span><strong>${say('Бергамот','Bergamot')}</strong><i>·</i><strong>${say('Ирис','Iris')}</strong><i>·</i><strong>${say('Кедр','Cedar')}</strong></div><a href="#/collection/fragrance" class="text-link">${say('Открыть парфюмерию','Explore perfumery')}</a></div></div></section>`}
function genesisFocus(){return `<figure class="genesis-main"><img src="${genesisImage(activeGenesis)}" alt="AMRA Dubai Genesis #${genesisNumber(activeGenesis)} — ${genesisNames[activeGenesis-1]}" width="500" height="500"><figcaption><span>AMRA DUBAI GENESIS</span><span>#${genesisNumber(activeGenesis)}</span></figcaption></figure><div class="genesis-caption"><span class="genesis-folio" aria-hidden="true">${String(activeGenesis).padStart(2,'0')}<small>/ 10</small></span><p class="eyebrow">${say('ВЫБРАННАЯ РАБОТА','SELECTED WORK')} / #${genesisNumber(activeGenesis)}</p><h3>${genesisNames[activeGenesis-1]}</h3><a href="${genesisBase+activeGenesis}" class="text-link" target="_blank" rel="noopener noreferrer">${say('Работа на OpenSea','View on OpenSea')}${I.arrow}</a></div>`}
function digitalShowcase(){return `<section class="genesis-section" id="digital-art"><div class="wrap"><div class="genesis-top"><p class="eyebrow">05 / DIGITAL ART</p><a href="https://opensea.io/AMRA-NFT" target="_blank" rel="noopener noreferrer">AMRA-NFT</a></div><div class="genesis-heading"><div><p class="eyebrow">${say('ЦИФРОВАЯ КОЛЛЕКЦИЯ AMRA','AN AMRA DIGITAL COLLECTION')}</p><h2>Dubai <br><em>Genesis.</em></h2></div><div><p class="genesis-lead">${say('Город, в котором<br>воображение обретает форму.','A city where<br>imagination takes shape.')}</p><p>${say('Десять цифровых работ. Панорамы будущего, свет пустыни и ритм Дубая — в коллекции AMRA Dubai Genesis. Выберите работу и рассмотрите её ближе.','Ten digital works. Future panoramas, desert light and the rhythm of Dubai in AMRA Dubai Genesis. Select a work and take a closer look.')}</p><a class="text-link" href="${genesisCollection}" target="_blank" rel="noopener noreferrer">${say('Вся коллекция на OpenSea','The collection on OpenSea')}${I.arrow}</a></div></div><div class="genesis-stage" id="genesis-stage" aria-live="polite">${genesisFocus()}</div><div class="genesis-strip" role="group" aria-label="${say('Выберите работу коллекции','Choose a collection work')}">${genesisNames.map((name,i)=>`<button data-genesis="${i+1}" aria-pressed="${activeGenesis===i+1}" aria-controls="genesis-stage" aria-label="#${genesisNumber(i+1)} — ${name}" title="${name}"><img src="${genesisImage(i+1)}" alt="" loading="lazy" width="500" height="500"><span>${genesisNumber(i+1)}</span></button>`).join('')}</div><div class="genesis-bottom"><span>${say('10 РАБОТ / ОДНА ИСТОРИЯ ГОРОДА','10 WORKS / ONE CITY’S STORY')}</span><a class="text-link" href="#/digital">${say('Открыть галерею AMRA','Enter the AMRA gallery')}</a></div></div></section>`}
function selectGenesis(n){if(n<1||n>10)return;activeGenesis=n;$('#genesis-stage').innerHTML=genesisFocus();document.querySelectorAll('[data-genesis]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.genesis)===n))}
function digital(){return `<div class="wrap"><div class="page-head">${breadcrumb(tr('digital'))}<p class="eyebrow">AMRA DIGITAL ART</p><h1>Dubai <em>Genesis.</em></h1><p class="description">${say('Десять взглядов на Дубай. Откройте работы коллекции AMRA Dubai Genesis — от первой истории пустыни до города будущего.','Ten visions of Dubai. Discover AMRA Dubai Genesis, from the first desert story to a city of the future.')}</p><a class="text-link" href="${genesisCollection}" target="_blank" rel="noopener noreferrer">${say('Коллекция на OpenSea','Collection on OpenSea')}${I.arrow}</a></div><div class="genesis-grid">${genesisNames.map((name,i)=>`<a class="genesis-card" href="${genesisBase+(i+1)}" target="_blank" rel="noopener noreferrer"><figure><img src="${genesisImage(i+1)}" alt="${name}" loading="lazy" width="500" height="500"><span>${say('СМОТРЕТЬ НА OPENSEA','VIEW ON OPENSEA')} ${arrowSvg()}</span></figure><div><span class="eyebrow">#${genesisNumber(i+1)}</span><h2>${name}</h2></div></a>`).join('')}</div><p class="genesis-page-note">${say('Изображения и названия — из коллекции AMRA Dubai Genesis на OpenSea. Актуальные условия доступны на странице каждой работы.','Images and titles from AMRA Dubai Genesis on OpenSea. Current terms are available on each work’s page.')}</p></div>${concierge()}`}

function acquisitionProcess(){const steps=[
 [say('Вы выбираете предмет','You find your piece'),say('Исследуйте коллекцию или расскажите, что ищете: для себя, в подарок или для пространства.','Explore the collection or tell us what you have in mind: for yourself, as a gift or for your space.')],
 [say('Мы уточняем детали','We clarify the details'),say('Обсуждаем ваш выбор, проверяем наличие и отвечаем на вопросы о предмете.','We discuss your choice, check availability and answer your questions about the piece.')],
 [say('Согласуем приобретение','We agree the terms'),say('Уточняем стоимость, способ оплаты и условия получения. Все детали — до вашего решения.','We confirm the price, payment method and delivery terms. Every detail is clear before you decide.')],
 [say('Организуем получение','We arrange the handover'),say('Согласуем доставку или передачу предмета и остаёмся на связи до его получения.','We arrange delivery or a personal handover and stay in touch until the piece reaches you.')]
];return `<section class="acquisition-process" id="how-to-acquire"><div class="wrap"><div class="process-heading"><div><p class="process-label"><span aria-hidden="true"></span>${say('КАК ПРИОБРЕСТИ','HOW TO ACQUIRE')}</p><h2>${say('Четыре шага<br><em>к вашей коллекции.</em>','Four steps<br><em>to your collection.</em>')}</h2></div><p class="process-intro">${say('От первого интереса до получения предмета — понятный процесс с вниманием к вашему выбору. Мы помогаем разобраться в деталях и остаёмся на связи на каждом этапе.','From your first discovery to receiving the piece — a clear process shaped around your choice. We guide you through the details and stay in touch at every step.')}</p></div><ol class="acquisition-timeline">${steps.map(([title,desc],i)=>`<li class="acquisition-step" style="--step:${i}"><div class="process-marker" aria-hidden="true"><span></span></div><p class="process-index">${say('ЭТАП','STEP')} · 0${i+1}</p><h3>${title}</h3><p class="process-description">${desc}</p></li>`).join('')}</ol><div class="process-digital-note"><p>${say('Цифровое искусство — отдельный путь: работы AMRA Dubai Genesis доступны на OpenSea.','Digital art has its own path: discover AMRA Dubai Genesis on OpenSea.')}</p><a href="${genesisCollection}" target="_blank" rel="noopener noreferrer">${say('Открыть коллекцию','Explore the collection')}${I.arrow}</a></div></div></section>`}
let revealObserver;
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function initMotion(){revealObserver?.disconnect();document.body.classList.add('motion-ready');document.querySelectorAll('.section-head,.category-tile,.category-digital-link,.product-card,.scent-copy,.edits-heading,.edit-stage,.digital-feature-copy,.atelier-photo,.journal-heading,.genesis-heading,.genesis-card,.steps article,.process-heading,.acquisition-timeline,.concierge-inner,.piece-info,.piece-image').forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--delay',(el.classList.contains('product-card')?i%4*65:0)+'ms')});if(reduceMotion.matches){document.querySelectorAll('.reveal').forEach(el=>el.classList.add('in-view'));return;}revealObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');revealObserver.unobserve(e.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));}
let scrollQueued=false;function syncScroll(){scrollQueued=false;const progress=document.getElementById('reading-progress');if(progress)progress.style.transform=`scaleX(${window.scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)})`;}
window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(syncScroll)}},{passive:true});
document.addEventListener('pointermove',e=>{if(reduceMotion.matches||e.pointerType!=='mouse')return;const pic=e.target.closest('.product-picture');if(!pic)return;const r=pic.getBoundingClientRect();pic.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*9+'px');pic.style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*9+'px');});
window.addEventListener('hashchange',()=>{render();syncScroll()});render();
